class Solution {
    public int countWords(String[] words1,String[] words2){
        Map<String,Integer> first=new HashMap<>(),second=new HashMap<>();
        for(String word:words1)first.merge(word,1,Integer::sum);
        for(String word:words2)second.merge(word,1,Integer::sum);
        int answer=0;
        for(Map.Entry<String,Integer> entry:first.entrySet())if(entry.getValue()==1&&second.getOrDefault(entry.getKey(),0)==1)answer++;
        return answer;
    }
}

code.kotlin:
class Solution {
    fun countWords(words1:Array<String>,words2:Array<String>):Int{
        val first=words1.groupingBy{
            it
        }.eachCount();
        val second=words2.groupingBy{
            it
        }.eachCount();
        return first.count{
            it.value==1&&second[it.key]==1
        }
    }
}

code.cpp:
class Solution {
    public: int countWords(vector<string>& words1,vector<string>& words2){
        unordered_map<string,int> first,second;
        for(string& word:words1)++first[word];
        for(string& word:words2)++second[word];
        int answer=0;
        for(auto [word,count]:first)answer+=count==1&&second[word]==1;
        return answer;
    }
};
